const [u, v] = field(p.x, p.y);
p.x += u * SPEED * dt;
p.y += v * SPEED * dt;

for (let j = 0; j < TRAIL / dt; j++) {
  path[band(j)].lineTo(hist[k - j].x, hist[k - j].y);
}

const speedClass = mag < 0.55 ? 0 : mag < 1.1 ? 1 : 2;
ctx.globalCompositeOperation = 'lighter';
ctx.strokeStyle = COLORS[speedClass];
